"""Check test conditions in scenario results input.

    Check whether the input parameters of a behave scenario results record from
    testapi match the input parameters of the latest test.  In other words,
    check that the test results from testapi come from a test done under the
    same conditions (frame size, flow count, rate, ...)

    Args:
        input: input dict of a results dict of a behave scenario from testapi

        result: dict of nfvbench params used during the last test

    Returns:
        True if test conditions match, else False.

    """
def get_result_from_input_values(input: Any, result: Any) -> object {
    required_keys = ['duration_sec', 'frame_sizes', 'flow_count', 'rate'];
    if ('user_label' in result) {
        required_keys.append('user_label');
    }
    if ('flavor_type' in result) {
        required_keys.append('flavor_type');
    }
    subset_input = `dict(
        (k, input[k])
        for k in required_keys
        if (k in input)
    );
    subset_result = `dict(
        (k, result[k])
        for k in required_keys
        if (k in result)
    );
    return (subset_input == subset_result);
}

"""
        Return top three score from the list. if there are less than 3
        scores then return in a decending order the all elements
    """
def personal_top_three(scores: Any) -> object {
    sorted_scores = sorted(scores, reverse=True);
    if (len(scores) >= 3) {
        return sorted_scores[:3];
    }
    return sorted_scores[:len(scores)];
}

"""
    Invert a dictionary

    :param dictionary:
    :return inverted_dictionary:
    """
def invert_dictionary(dictionary: Any) -> object {
    inverted_dictionary = `dict();
    for (k, v) in dictionary.items() {
        inverted_dictionary[v] = k;
    }
    return inverted_dictionary;
}

"""
    This method finds a du id associated to an ip
    """
def find_du_based_on_ip(ip: Any, functions: Any) -> object {
    for vnf in functions {
        if ('vnfr' not in vnf.keys()) {
            continue;
        }
        vnfr = vnf['vnfr'];
        dus = [];
        if ('virtual_deployment_units' in vnfr.keys()) {
            dus = vnfr['virtual_deployment_units'];
        }
        if ('couldnative_deployment_units' in vnfr.keys()) {
            dus = vnfr['cloudnative_deployment_units'];
        }
        for du in dus {
            du_string = str(du);
            if (ip in du_string) {
                return (du['id'], vnf['id']);
            }
        }
    }
    return (None, None);
}

